import json,sys,platform
import numpy as np
from scipy import optimize,linalg
import scipy
SEED=892104

def cov(code,t,p):
    t=np.asarray(t,float);m=len(t);p=np.asarray(p,float)
    if code==0: return np.diag(p)
    if code==1:
        v=np.zeros((m,m));v[np.tril_indices(m)]=p
        return v+v.T-np.diag(np.diag(v))
    if code in (2,4,5,8): sd=np.repeat(np.sqrt(p[0]),m);r=p[1:]
    else: sd=np.sqrt(p[:m]);r=p[m:]
    if code in (2,3): c=np.full((m,m),r[0]);np.fill_diagonal(c,1)
    elif code==4: c=r[0]**np.abs(t[:,None]-t[None,:])
    elif code in (5,6):
        c=np.eye(m)
        for i in range(m):
            for j in range(i):c[i,j]=c[j,i]=r[i-j-1]
    elif code in (7,8):
        c=np.eye(m)
        for i in range(m):
            for j in range(i): c[i,j]=c[j,i]=np.prod(r[j:i])
    return sd[:,None]*c*sd[None,:]

def profile(y,x,v,reml):
    # Independent oracle: full covariance eigendecomposition and dense inverse.
    # Does not use production block Cholesky / Householder QR.
    w,u=np.linalg.eigh(v)
    if min(w)<=0:return None
    vi=(u/w)@u.T
    info=x.T@vi@x
    sign,ldx=np.linalg.slogdet(info)
    if sign<=0:return None
    beta=np.linalg.solve(info,x.T@vi@y)
    e=y-x@beta;q=e@vi@e
    n,k=x.shape;df=n-k if reml else n
    s=q/df
    ll=-.5*(df*(np.log(2*np.pi)+1+np.log(s))+np.log(w).sum()+(ldx if reml else 0))
    return dict(beta=beta,scale=s,log_likelihood=ll,covariance=np.linalg.inv(info)*s,residuals=e)

def random_fixture(reml):
    rng=np.random.default_rng(SEED)
    sizes=[3,4,5,3,5,4,3,5,4,5,3,5]
    G=np.array([[1.4,.3],[.3,.6]]);sig=.22
    u=[];y=[];g=[]
    for i,n in enumerate(sizes):
        tt=np.sort(rng.uniform(-1.8,2.1,n)); b=rng.multivariate_normal([0,0],G)
        u.extend(tt); y.extend(2.3+1.2*tt+b[0]+tt*b[1]+rng.normal(0,np.sqrt(sig),n));g.extend([i]*n)
    u=np.asarray(u);y=np.asarray(y);g=np.asarray(g)
    x=np.c_[np.ones(len(y)),u]
    def build(theta):
        L=np.array([[np.exp(theta[0]),0],[theta[1],np.exp(theta[2])]])
        gg=L@L.T;v=np.eye(len(y))
        for group in np.unique(g):
            ix=np.flatnonzero(g==group); z=x[ix]
            v[np.ix_(ix,ix)]+=z@gg@z.T
        return v,gg
    def obj(theta):
        try:
            v,_=build(theta);r=profile(y,x,v,reml)
            return -r['log_likelihood'] if r else 1e100
        except (ValueError,OverflowError,np.linalg.LinAlgError):return 1e100
    starts=[[-.2,.1,-.2],[.5,.2,.2],[-1,0,-1]]
    fits=[optimize.minimize(obj,s,method='BFGS',options={'gtol':1e-8,'maxiter':1000}) for s in starts]
    fit=min(fits,key=lambda r:r.fun)
    v,gg=build(fit.x);r=profile(y,x,v,reml);r['G']=gg*r['scale']
    r['theta']=fit.x;r['data']=np.c_[u,y,g]
    vi=np.linalg.inv(v*r['scale']); e=y-x@r['beta']
    r['blups']=[]
    for group in np.unique(g):
        ix=np.flatnonzero(g==group)
        r['blups'].append(r['G']@x[ix].T@vi[np.ix_(ix,ix)]@e[ix])
    return r
def serial(v):
    if isinstance(v,np.ndarray):return v.tolist()
    if isinstance(v,np.floating):return float(v)
    raise TypeError(type(v))
if __name__=='__main__':
    out={'seed':SEED,'python':sys.version,'numpy':np.__version__,'scipy':scipy.__version__}
    for mode in (False,True):out['random_slope_'+('REML' if mode else 'ML')]=random_fixture(mode)
