        print(mode,'beta',r['beta'],'sigma2',r['scale'],'G',r['G'],'LL',r['log_likelihood'])
def repeated_fixture(code=4,reml=True):
    rng=np.random.default_rng(SEED+code)
    ts=np.array([0.,1.,2.,3.])
    params={0:[.5,.9,.7,1.2],1:[1,.2,.9,.1,.25,.8,.05,.1,.3,1.1],2:[.8,.35],3:[.5,.9,.7,1.2,.35],4:[.8,.55],5:[.8,.4,.2,.1],6:[.5,.9,.7,1.2,.4,.2,.1],7:[.5,.9,.7,1.2,.3,.5,-.2],8:[.8,.3,.5,-.2]}[code]
    c=cov(code,ts,params); rows=[]
    for j in range(16):
        ix=np.arange(4) if j%3 else np.array([0,2,3])
        trt=float(j%2);x=np.c_[np.ones(len(ix)),np.repeat(trt,len(ix)),ts[ix]]
        yy=x@np.array([1.1,.7,.35])+rng.multivariate_normal(np.zeros(len(ix)),c[np.ix_(ix,ix)])
        rows.extend(np.c_[np.repeat(trt,len(ix)),ts[ix],yy,np.repeat(j,len(ix)),ts[ix]])
    rows=np.array(rows);x=np.c_[np.ones(len(rows)),rows[:,:2]];y=rows[:,2]
    v=np.zeros((len(rows),len(rows)))
    for group in np.unique(rows[:,3]):
        ix=np.flatnonzero(rows[:,3]==group);ti=rows[ix,4].astype(int);v[np.ix_(ix,ix)]=c[np.ix_(ti,ti)]
    iv=np.linalg.inv(v);info=x.T@iv@x;beta=np.linalg.solve(info,x.T@iv@y);res=y-x@beta
    ll=-.5*(len(y)*np.log(2*np.pi)+np.linalg.slogdet(v)[1]+res@iv@res)
    return dict(data=rows,parameters=params,covariance=c,beta=beta,beta_covariance=np.linalg.inv(info),log_likelihood=ll)
